 [('AI Investigator','AI Investigator'),('برنامهٔ کاربردی؛ فرضیه‌سازی و بررسی با ابزارهای محدود.','Application layer: hypothesis generation and bounded tool investigation.'),('علت‌یابی روی سناریوهای نگه‌داشته‌شده و گزارش مستند.','Diagnosis on held-out incidents and evidence-backed reports.')],
 [('Evaluation & Release','Evaluation & Release'),('dataset، trial، scorer و ارتقای نسخهٔ ثابت‌شده.','Datasets, trials, scoring, and pinned-release promotion.'),('ردِ regression و canary/rollback قابل‌تکرار.','A reproducible regression rejection, and a canary/rollback you can repeat.')],
