 [('Step / ToolCall','Step / ToolCall'),('step_id، operation_key، input_hash، state، result_ref، attempt، owner_epoch.','step_id, operation_key, input_hash, state, result_ref, attempt, owner_epoch.'),('کلیدِ عملیات از run+step+intent ساخته می‌شه؛ و retry همون کلید رو نگه می‌داره.','The operation key comes from run+step+intent, and the retries keep it.')],
