 [('API پس از commit و پیش از پاسخ','API dies after commit, before response'),('retry همون idempotency key؛ و run قبلی خونده می‌شه.','Retry the same idempotency key and retrieve the existing run.'),('یه run؛ و request hash متفاوت conflict.','One run, and a conflicting request hash gets rejected.')],
 [('worker pause یا crash','Worker pause/crash'),('lease با epoch تازه؛ و commit مالکِ قدیمی رد بشه.','New lease epoch; reject stale-owner commits.'),('آخرین step پایدار حفظ شده و guard SQL اجرا شده.','The last durable step survives, and the SQL guard gets exercised.')],
 [('provider timeout','Provider timeout'),('attempt ثبت می‌شه، سقفِ retry و رزروِ pending؛ و نتیجه/هزینهٔ نامعلوم reconcile.','Record attempts, cap retries, retain pending reservation, reconcile uncertain outcome/cost.'),('از سقفِ token/deadline عبور نکن؛ و double-charge بی‌صدا نباشه.','No token or deadline overrun, and no silent duplicate billing.')],
 [('Kafka / CDC outage','Kafka/CDC outage'),('backlog و WAL monitor؛ pause seed؛ و از دست‌رفتنِ cursor یعنی resnapshot.','Monitor backlog/WAL, pause seeds, resnapshot on lost cursors.'),('هیچ gap پنهانی نیست؛ گزارشِ degraded و cut معتبر.','No hidden gap; an explicit degraded state and a valid cut.')],
 [('poison event / schema ناسازگار','Poison event/incompatible schema'),('quarantine با metadata کمینه؛ و entity تا repair degraded می‌مونه.','Quarantine minimal metadata; affected entities stay degraded until repair.'),('offset/نسخهٔ خطادار و recovery قابل‌مشاهده.','A visible failed offset/revision and the recovery path.')],
 [('مرگِ projector وسط embedding','Projector dies mid-embedding'),('artifact موقت؛ publish فقط با revision+epoch معتبر؛ و retry همون generation.','Temporary artifact; publish only with valid revision/epoch; retry the same generation.'),('v قدیمی و chunk orphan نباید توی retrieval ظاهر بشن.','A stale revision and an orphan chunk never show up in the retrieval.')],
